class TopVotedCandidate:
    def __init__(self, persons, times):
        self.persons = persons
        self.times = times

    def q(self, t):
        from collections import defaultdict
        cnt = defaultdict(int)
        leader, best = -1, 0
        for p, tm in zip(self.persons, self.times):
            if tm > t:
                break
            cnt[p] += 1
            if cnt[p] >= best:
                best = cnt[p]
                leader = p
        return leader

