class TopVotedCandidate {
    private int[] persons, times;
    public TopVotedCandidate(int[] persons, int[] times) {
        this.persons = persons;
        this.times = times;
    }

    public int q(int t) {
        Map<Integer,Integer> cnt = new HashMap<>();
        int leader = -1, best = 0;
        for (int i = 0; i < times.length && times[i] <= t; i++) {
            int c = cnt.merge(persons[i], 1, Integer::sum);
            if (c >= best) { best = c; leader = persons[i]; }
        }
        return leader;
    }
}

