class TopVotedCandidate {
    vector<int> times, leaders;
public:
    TopVotedCandidate(vector<int>& persons, vector<int>& times_) : times(times_) {
        unordered_map<int,int> cnt;
        int leader = -1, best = 0;
        for (int p : persons) {
            if (++cnt[p] >= best) { best = cnt[p]; leader = p; }
            leaders.push_back(leader);
        }
    }

    int q(int t) {
        int lo = 0, hi = times.size() - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (times[mid] <= t) lo = mid; else hi = mid - 1;
        }
        return leaders[lo];
    }
};

