    public int q(int t) {
        int lo = 0, hi = times.length - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) >>> 1;
            if (times[mid] <= t) lo = mid; else hi = mid - 1;
        }
        return leaders[lo];
    }
}

